import ast

def truthy(v):
    if v is True:
        return True
    if isinstance(v, str) and v.strip() in {'True', 'true'}:
        return True
    return False

def has_bus_parking(attrs):
    if not attrs:
        return False
    bp = attrs.get('BusinessParking')
    if bp is None:
        return False
    if isinstance(bp, dict):
        return any(truthy(v) for v in bp.values())
    if isinstance(bp, str):
        try:
            parsed = ast.literal_eval(bp)
            if isinstance(parsed, dict):
                return any(truthy(v) for v in parsed.values())
        except Exception:
            pass
        # fallback: substring check
        return 'True' in bp
    return False

def has_bike_parking(attrs):
    if not attrs:
        return False
    return truthy(attrs.get('BikeParking'))

qualifying = []
bike_only = bus_only = both = 0
for d in docs:
    attrs = d.get('attributes')
    bp = has_bus_parking(attrs)
    bk = has_bike_parking(attrs)
    if bp or bk:
        qualifying.append(d['business_id'])
        if bp and bk:
            both += 1
        elif bp:
            bus_only += 1
        else:
            bike_only += 1

print("qualifying total:", len(qualifying))
print("both:", both, "bus_only:", bus_only, "bike_only:", bike_only)
print("sample qualifying:", qualifying[:5])

